def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees a solution.
    """
    if not xs:
        return 0.0

    def poly_eval(x):
        res = 0
        for coeff in reversed(xs):
            res = res * x + coeff
        return res

    # Find the degree and the leading coefficient (last non-zero)
    n = len(xs) - 1
    while n >= 0 and xs[n] == 0:
        n -= 1
    if n < 0:
        return 0.0
    a_n = xs[n]

    # Cauchy's Bound for roots of a polynomial: |x| < 1 + max(|a_i| / |a_n|)
    max_abs_coeff = 0
    for i in range(n):
        max_abs_coeff = max(max_abs_coeff, abs(xs[i]))
    R = 1 + max_abs_coeff / abs(a_n)

    # Use a step-based search to find the first sign change from -R to R.
    # This ensures we find the smallest root if multiple exist in this range.
    # Odd degree polynomials are guaranteed to have at least one real root in [-R, R].
    steps = max(2000, int(4 * R))
    low_bound = -R
    high_bound = R

    for i in range(steps):
        x1 = low_bound + (high_bound - low_bound) * i / steps
        x2 = low_bound + (high_bound - low_bound) * (i + 1) / steps
        f1 = poly_eval(x1)
        f2 = poly_eval(x2)

        if f1 == 0:
            return float(x1)
        if f2 == 0:
            return float(x2)

        if (f1 > 0) != (f2 > 0):
            # Bisection method within the identified interval [x1, x2]
            low = x1
            high = x2
            f_low = f1
            for _ in range(64):
                mid = (low + high) / 2
                f_mid = poly_eval(mid)
                if f_mid == 0:
                    return float(mid)
                if (f_low > 0) != (f_mid > 0):
                    high = mid
                else:
                    low = mid
                    f_low = f_mid
            return float((low + high) / 2)

    # Fallback for cases where no sign change was caught by step search due to precision.
    # This should not be reached given the problem constraints and Cauchy's bound.
    return 0.0
